CREATE TABLE IF NOT EXISTS schema_migrations (version INTEGER PRIMARY KEY, applied_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS tenant (id TEXT PRIMARY KEY, public_id TEXT NOT NULL UNIQUE, name TEXT NOT NULL, plan TEXT NOT NULL CHECK(plan IN ('standard','enterprise')), mode TEXT NOT NULL CHECK(mode IN ('normal','admin_working','maintenance','suspended')), ip_allowlist TEXT NOT NULL DEFAULT '[]', allowed_email_domains TEXT NOT NULL DEFAULT '[]', self_service_proxy INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS grades (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, level INTEGER NOT NULL UNIQUE, is_default INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, email TEXT NOT NULL UNIQUE COLLATE NOCASE, first_name TEXT NOT NULL, last_name TEXT NOT NULL, employee_id TEXT, status TEXT NOT NULL, locale TEXT NOT NULL, user_type TEXT NOT NULL, custom_fields TEXT NOT NULL DEFAULT '{}', last_used_on TEXT, deactivated_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS user_invitations (id TEXT PRIMARY KEY, user_id TEXT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE, user_email TEXT NOT NULL, user_locale TEXT NOT NULL, expires_at INTEGER NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS organization_charts (id TEXT PRIMARY KEY, name TEXT NOT NULL, current INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS teams (id TEXT PRIMARY KEY, organization_chart_id TEXT NOT NULL REFERENCES organization_charts(id) ON DELETE CASCADE, code TEXT NOT NULL, name TEXT NOT NULL, notes TEXT, parent_id TEXT REFERENCES teams(id) ON DELETE SET NULL, approve_only INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(organization_chart_id, code));
CREATE TABLE IF NOT EXISTS team_memberships (id TEXT PRIMARY KEY, team_id TEXT NOT NULL REFERENCES teams(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, leader INTEGER NOT NULL DEFAULT 0, grade_ids TEXT NOT NULL DEFAULT '[]', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(team_id,user_id));
CREATE TABLE IF NOT EXISTS roles (id TEXT PRIMARY KEY, name TEXT NOT NULL, editable INTEGER NOT NULL DEFAULT 1, permission_list TEXT NOT NULL DEFAULT '[]', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS role_memberships (role_id TEXT NOT NULL REFERENCES roles(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, created_at INTEGER NOT NULL, PRIMARY KEY(role_id,user_id));
CREATE TABLE IF NOT EXISTS categories (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS folders (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, description TEXT, parent_id TEXT REFERENCES folders(id) ON DELETE SET NULL, editable INTEGER NOT NULL DEFAULT 1, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS general_masters (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, description TEXT, default_sort_by TEXT NOT NULL DEFAULT '', initial_display_code INTEGER NOT NULL DEFAULT 0, initial_display_created_at INTEGER NOT NULL DEFAULT 0, initial_display_description INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS general_master_fields (id TEXT PRIMARY KEY, general_master_id TEXT NOT NULL REFERENCES general_masters(id) ON DELETE CASCADE, code TEXT NOT NULL, title TEXT NOT NULL, description TEXT, field_type TEXT NOT NULL, required INTEGER NOT NULL DEFAULT 0, field_order INTEGER NOT NULL, visible INTEGER NOT NULL DEFAULT 1, initial_display INTEGER NOT NULL DEFAULT 0, options TEXT, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(general_master_id,code));
CREATE TABLE IF NOT EXISTS general_master_items (id TEXT PRIMARY KEY, general_master_id TEXT NOT NULL REFERENCES general_masters(id) ON DELETE CASCADE, code TEXT NOT NULL, name TEXT NOT NULL, description TEXT, starts_on TEXT, ends_on TEXT, inputs TEXT NOT NULL DEFAULT '[]', input_ids TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(general_master_id,code));
CREATE TABLE IF NOT EXISTS routes (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, status TEXT NOT NULL, folder_id TEXT NOT NULL REFERENCES folders(id), definition_json TEXT NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS workflows (id TEXT PRIMARY KEY, code TEXT NOT NULL UNIQUE, status TEXT NOT NULL, folder_id TEXT NOT NULL REFERENCES folders(id), definition_json TEXT NOT NULL, ticket_number_counter INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS proxy_applicants (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, proxy_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, starts_on TEXT, ends_on TEXT, workflow_ids TEXT NOT NULL DEFAULT '[]', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(user_id,proxy_user_id));
CREATE TABLE IF NOT EXISTS proxy_approvers (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, proxy_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, starts_on TEXT, ends_on TEXT, workflow_ids TEXT NOT NULL DEFAULT '[]', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(user_id,proxy_user_id));
CREATE TABLE IF NOT EXISTS tickets (id TEXT PRIMARY KEY, workflow_id TEXT NOT NULL REFERENCES workflows(id), status TEXT NOT NULL, current_step INTEGER NOT NULL DEFAULT 0, title TEXT, ticket_number TEXT, author_id TEXT REFERENCES users(id) ON DELETE SET NULL, author_team_id TEXT REFERENCES teams(id) ON DELETE SET NULL, author_team_snapshot TEXT, proxy_client_user_id TEXT REFERENCES users(id) ON DELETE SET NULL, forced_public_type TEXT NOT NULL DEFAULT '', route_id TEXT REFERENCES routes(id) ON DELETE SET NULL, opened_at INTEGER, completed_at INTEGER, denied_at INTEGER, archived_at INTEGER, closed_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ticket_inputs (id TEXT PRIMARY KEY, ticket_id TEXT NOT NULL REFERENCES tickets(id) ON DELETE CASCADE, form_field_id TEXT NOT NULL, value TEXT NOT NULL, ref_ids TEXT NOT NULL DEFAULT '[]', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL, UNIQUE(ticket_id,form_field_id));
CREATE TABLE IF NOT EXISTS ticket_slip_items (id TEXT PRIMARY KEY, ticket_id TEXT NOT NULL REFERENCES tickets(id) ON DELETE CASCADE, slip_section_id TEXT NOT NULL, position INTEGER NOT NULL, inputs TEXT NOT NULL DEFAULT '{}', created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ticket_steps (id TEXT PRIMARY KEY, ticket_id TEXT NOT NULL REFERENCES tickets(id) ON DELETE CASCADE, route_step_id TEXT, route_step_code TEXT, step_order INTEGER NOT NULL, display_order INTEGER NOT NULL, title TEXT, action_type TEXT NOT NULL, required_approvals_number INTEGER NOT NULL DEFAULT 0, required_approvals_percent INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL, skip INTEGER NOT NULL DEFAULT 0, fallback INTEGER NOT NULL DEFAULT 0, fallback_result TEXT, completed_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ticket_assignees (id TEXT PRIMARY KEY, ticket_step_id TEXT NOT NULL REFERENCES ticket_steps(id) ON DELETE CASCADE, ticket_id TEXT NOT NULL REFERENCES tickets(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id), completed INTEGER NOT NULL DEFAULT 0, completed_at INTEGER, actual_approver_id TEXT REFERENCES users(id) ON DELETE SET NULL, assigned_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS ticket_custom_approvers (ticket_id TEXT NOT NULL REFERENCES tickets(id) ON DELETE CASCADE, route_step_code TEXT NOT NULL, user_ids TEXT NOT NULL DEFAULT '[]', PRIMARY KEY(ticket_id,route_step_code));
CREATE TABLE IF NOT EXISTS ticket_viewers (id TEXT PRIMARY KEY, ticket_id TEXT NOT NULL REFERENCES tickets(id) ON DELETE CASCADE, user_id TEXT REFERENCES users(id) ON DELETE CASCADE, team_id TEXT REFERENCES teams(id) ON DELETE CASCADE, grade_id TEXT REFERENCES grades(id) ON DELETE CASCADE, descendants INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS ticket_links (ticket_id TEXT NOT NULL REFERENCES tickets(id) ON DELETE CASCADE, linked_ticket_id TEXT NOT NULL REFERENCES tickets(id) ON DELETE CASCADE, created_at INTEGER NOT NULL, PRIMARY KEY(ticket_id,linked_ticket_id));
CREATE TABLE IF NOT EXISTS comments (id TEXT PRIMARY KEY, ticket_id TEXT NOT NULL REFERENCES tickets(id) ON DELETE CASCADE, user_id TEXT NOT NULL REFERENCES users(id), body TEXT NOT NULL, mentioned_user_ids TEXT NOT NULL DEFAULT '[]', deleted_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS files (id TEXT PRIMARY KEY, signed_id TEXT NOT NULL UNIQUE, filename TEXT NOT NULL, content_type TEXT NOT NULL, byte_size INTEGER NOT NULL, checksum TEXT NOT NULL, storage_name TEXT NOT NULL, uploaded_by TEXT REFERENCES users(id) ON DELETE SET NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS file_attachments (file_id TEXT NOT NULL REFERENCES files(id) ON DELETE CASCADE, ticket_id TEXT NOT NULL REFERENCES tickets(id) ON DELETE CASCADE, comment_id TEXT REFERENCES comments(id) ON DELETE CASCADE, form_field_id TEXT, slip_item_id TEXT, created_at INTEGER NOT NULL, PRIMARY KEY(file_id,ticket_id,comment_id,form_field_id,slip_item_id));
CREATE TABLE IF NOT EXISTS audit_logs (id TEXT PRIMARY KEY, user_id TEXT REFERENCES users(id) ON DELETE SET NULL, action TEXT NOT NULL, data TEXT, remote_ip TEXT, request_id TEXT, system_type TEXT, ticket_id TEXT REFERENCES tickets(id) ON DELETE SET NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS api_tokens (id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('pat','sat')), name TEXT NOT NULL, description TEXT, token_hash TEXT NOT NULL UNIQUE, user_id TEXT REFERENCES users(id) ON DELETE CASCADE, fixture_plaintext TEXT, created_at INTEGER NOT NULL, last_used_at INTEGER);
CREATE TABLE IF NOT EXISTS sessions (id_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, csrf_token TEXT NOT NULL, created_at INTEGER NOT NULL, last_seen_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS oidc_states (state TEXT PRIMARY KEY, nonce TEXT NOT NULL, code_verifier TEXT NOT NULL, return_to TEXT NOT NULL, expires_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS webhooks (id TEXT PRIMARY KEY, name TEXT NOT NULL, url TEXT NOT NULL, secret TEXT, enabled INTEGER NOT NULL DEFAULT 1, workflow_ids TEXT NOT NULL DEFAULT '[]', event_types TEXT NOT NULL DEFAULT '[]', first_failure_at INTEGER, disabled_at INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS webhook_events (id TEXT PRIMARY KEY, webhook_id TEXT NOT NULL REFERENCES webhooks(id) ON DELETE CASCADE, event_type TEXT NOT NULL, ticket_id TEXT, comment_id TEXT, actor_user_id TEXT, body BLOB NOT NULL, status TEXT NOT NULL, attempt_count INTEGER NOT NULL DEFAULT 0, next_attempt_at INTEGER NOT NULL, last_status_code INTEGER, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS webhook_attempts (id TEXT PRIMARY KEY, event_id TEXT NOT NULL REFERENCES webhook_events(id) ON DELETE CASCADE, attempt_no INTEGER NOT NULL, started_at INTEGER NOT NULL, duration_ms INTEGER NOT NULL DEFAULT 0, request_headers TEXT NOT NULL DEFAULT '{}', status_code INTEGER, response_body BLOB, error TEXT, manual INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL, UNIQUE(event_id,attempt_no));
CREATE TABLE IF NOT EXISTS server_secrets (name TEXT PRIMARY KEY, value BLOB NOT NULL, created_at INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS idx_teams_org_chart ON teams(organization_chart_id);
CREATE INDEX IF NOT EXISTS idx_teams_parent ON teams(parent_id);
CREATE INDEX IF NOT EXISTS idx_team_memberships_user ON team_memberships(user_id);
CREATE INDEX IF NOT EXISTS idx_role_memberships_user ON role_memberships(user_id);
CREATE INDEX IF NOT EXISTS idx_gmf_master ON general_master_fields(general_master_id);
CREATE INDEX IF NOT EXISTS idx_gmi_master ON general_master_items(general_master_id);
CREATE INDEX IF NOT EXISTS idx_routes_folder ON routes(folder_id);
CREATE INDEX IF NOT EXISTS idx_workflows_folder ON workflows(folder_id);
CREATE INDEX IF NOT EXISTS idx_proxy_applicants_user ON proxy_applicants(user_id);
CREATE INDEX IF NOT EXISTS idx_proxy_approvers_user ON proxy_approvers(user_id);
CREATE INDEX IF NOT EXISTS idx_tickets_workflow ON tickets(workflow_id);
CREATE INDEX IF NOT EXISTS idx_tickets_author ON tickets(author_id);
CREATE INDEX IF NOT EXISTS idx_tickets_author_team ON tickets(author_team_id);
CREATE INDEX IF NOT EXISTS idx_ticket_inputs_ticket ON ticket_inputs(ticket_id);
CREATE INDEX IF NOT EXISTS idx_ticket_slip_items_ticket ON ticket_slip_items(ticket_id);
CREATE INDEX IF NOT EXISTS idx_ticket_steps_ticket ON ticket_steps(ticket_id);
CREATE INDEX IF NOT EXISTS idx_ticket_assignees_step ON ticket_assignees(ticket_step_id);
CREATE INDEX IF NOT EXISTS idx_ticket_assignees_ticket ON ticket_assignees(ticket_id);
CREATE INDEX IF NOT EXISTS idx_ticket_assignees_user ON ticket_assignees(user_id);
CREATE INDEX IF NOT EXISTS idx_ticket_viewers_ticket ON ticket_viewers(ticket_id);
CREATE INDEX IF NOT EXISTS idx_ticket_viewers_user ON ticket_viewers(user_id);
CREATE INDEX IF NOT EXISTS idx_ticket_viewers_team ON ticket_viewers(team_id);
CREATE INDEX IF NOT EXISTS idx_ticket_viewers_grade ON ticket_viewers(grade_id);
CREATE INDEX IF NOT EXISTS idx_ticket_links_linked ON ticket_links(linked_ticket_id);
CREATE INDEX IF NOT EXISTS idx_comments_ticket ON comments(ticket_id);
CREATE INDEX IF NOT EXISTS idx_comments_user ON comments(user_id);
CREATE INDEX IF NOT EXISTS idx_files_uploaded_by ON files(uploaded_by);
CREATE INDEX IF NOT EXISTS idx_file_attachments_ticket ON file_attachments(ticket_id);
CREATE INDEX IF NOT EXISTS idx_file_attachments_comment ON file_attachments(comment_id);
CREATE INDEX IF NOT EXISTS idx_audit_logs_created_at ON audit_logs(created_at);
CREATE INDEX IF NOT EXISTS idx_audit_logs_user ON audit_logs(user_id);
CREATE INDEX IF NOT EXISTS idx_audit_logs_ticket ON audit_logs(ticket_id);
CREATE INDEX IF NOT EXISTS idx_api_tokens_user ON api_tokens(user_id);
CREATE INDEX IF NOT EXISTS idx_sessions_user ON sessions(user_id);
CREATE INDEX IF NOT EXISTS idx_webhook_events_ready ON webhook_events(status,next_attempt_at);
CREATE INDEX IF NOT EXISTS idx_webhook_events_webhook ON webhook_events(webhook_id);
CREATE INDEX IF NOT EXISTS idx_webhook_attempts_event ON webhook_attempts(event_id);
